<style>.global-search-btn{position:fixed;right:22px;bottom:22px;z-index:9998;border:0;border-radius:999px;background:#183d31;color:#fff;padding:12px 18px;box-shadow:0 12px 30px rgba(24,61,49,.25);font:500 13px Prompt,sans-serif;cursor:pointer}.global-search-backdrop{display:none;position:fixed;inset:0;z-index:9999;background:rgba(10,22,16,.42);backdrop-filter:blur(5px);padding:7vh 18px}.global-search-backdrop.open{display:block}.global-search-box{width:min(720px,100%);margin:auto;background:#faf9f5;border-radius:24px;box-shadow:0 25px 80px rgba(0,0,0,.22);overflow:hidden}.global-search-head{display:flex;align-items:center;gap:10px;padding:18px;border-bottom:1px solid #dde2dc}.global-search-form{display:flex;flex:1;gap:10px}.global-search-input{flex:1;min-width:0;border:1px solid #d6ddd7;border-radius:14px;background:#fff;padding:13px 15px;font:400 14px Prompt,sans-serif;outline:none}.global-search-submit{border:0;border-radius:14px;background:#183d31;color:#fff;padding:0 18px;font:600 13px Prompt,sans-serif;cursor:pointer}.global-search-close{width:40px;height:40px;border:1px solid #d6ddd7;border-radius:12px;background:#fff;color:#68736c;font-size:22px;cursor:pointer}.global-search-hint{padding:0 22px 18px;color:#68736c;font-size:11px}@media(max-width:600px){.global-search-btn{right:14px;bottom:14px}.global-search-backdrop{padding:18px 12px}.global-search-form{flex-direction:column}.global-search-submit{height:44px}.global-search-box{border-radius:20px}}</style><button type="button" class="global-search-btn" id="globalSearchOpen">⌕ ค้นหาสถานที่</button><div class="global-search-backdrop" id="globalSearchBackdrop" aria-hidden="true"><div class="global-search-box" role="dialog" aria-modal="true"><div class="global-search-head"><form class="global-search-form" action="search.php" method="get"><input class="global-search-input" id="globalSearchInput" name="q" type="search" placeholder="ค้นหาสถานที่ ร้านอาหาร คาเฟ่..." autocomplete="off"><button class="global-search-submit" type="submit">ค้นหา</button></form><button type="button" class="global-search-close" id="globalSearchClose">×</button></div><div class="global-search-hint">ค้นหาได้จากชื่อสถานที่ ชื่อร้าน จังหวัด/อำเภอ หมวดหมู่ และรายละเอียด · กด Ctrl+K เพื่อค้นหา</div></div></div><script>(function(){const o=document.getElementById('globalSearchOpen'),b=document.getElementById('globalSearchBackdrop'),c=document.getElementById('globalSearchClose'),i=document.getElementById('globalSearchInput');if(!o||!b)return;function show(){b.classList.add('open');b.setAttribute('aria-hidden','false');setTimeout(()=>i&&i.focus(),30)}function hide(){b.classList.remove('open');b.setAttribute('aria-hidden','true')}o.addEventListener('click',show);c&&c.addEventListener('click',hide);b.addEventListener('click',e=>{if(e.target===b)hide()});document.addEventListener('keydown',e=>{if(e.key==='Escape')hide();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();show()}})})();</script>